function formatValidationError(error: ErrorObject): string {
  const path = error.dataPath ? `input${error.dataPath}` : 'input';
  const {params} = error;
  if ('missingProperty' in params) return `${path}: missing required property '${params.missingProperty}'`;
  if ('type' in params) return `${path}: expected type ${params.type}`;
  if ('allowedValues' in params) return `${path}: must match enum [${params.allowedValues.join(', ')}]`;
  return `${path}: failed ${error.keyword} constraint`;
}

