import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('Tool Input Validation', () => {
  it('validates input against inputSchema, returns ToolResponse on failure, and does not invoke executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'location_tool',
        description: 'gets location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        calls++;
        return 'success';
      }
    );

    const response = await registry.execute('location_tool', {});
    expect({calls, result: response.result}).toEqual({
      calls: 0,
      result: expect.stringMatching(/location/),
    });
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    let executorInput: unknown = null;
    let calls = 0;
    registry.register(
      {
        name: 'echo_tool',
        description: 'echos',
        inputSchema: {type: 'object', properties: {text: {type: 'string'}}, required: ['text']},
      },
      async input => {
        executorInput = input;
        calls++;
        return 'success';
      }
    );

    await registry.execute('echo_tool', {text: 'hello', extra: 'unlisted'});
    expect({calls, executorInput}).toEqual({
      calls: 1,
      executorInput: {text: 'hello', extra: 'unlisted'},
    });
  });

  it('rejects a wrong-typed field with a message naming the field path and expected type, without offending value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'type_tool',
        description: 'types',
        inputSchema: {type: 'object', properties: {count: {type: 'string'}}, required: ['count']},
      },
      async () => 'success'
    );

    const response = await registry.execute('type_tool', {count: 123456789});
    expect({
      result: response.result,
      hasOffendingValue: response.result.includes('123456789'),
    }).toEqual({
      result: expect.stringMatching(/count.*string|string.*count/),
      hasOffendingValue: false,
    });
  });

  it('throws at registration time for an uncompilable schema, and message names the tool', () => {
    const registry = new ToolRegistry();
    expect(() => {
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'bad',
          inputSchema: {type: 'invalid_type_here'},
        },
        async () => 'success'
      );
    }).toThrow(/bad_schema_tool/);
  });

  it('validates a function-valued definition against the schema current at that call, not a stale cached one', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    let schemaType = 'string';
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'dyn',
        inputSchema: {type: 'object', properties: {prop: {type: schemaType}}, required: ['prop']},
      }),
      async () => {
        calls++;
        return 'success';
      }
    );

    const firstResponse = await registry.execute('dynamic_tool', {prop: 'text'});
    const callsAfterFirst = calls;

    schemaType = 'number';
    const secondResponse = await registry.execute('dynamic_tool', {prop: 'text'});
    expect({
      firstResult: firstResponse.result,
      callsAfterFirst,
      callsAfterSecond: calls,
      secondResult: secondResponse.result,
    }).toEqual({
      firstResult: 'success',
      callsAfterFirst: 1,
      callsAfterSecond: 1,
      secondResult: expect.stringMatching(/number/),
    });
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let accesses = 0;
    const inputSchema = {
      get type() {
        accesses++;
        return 'object';
      },
      properties: {value: {type: 'string'}},
      required: ['value'],
    };
    registry.register({name: 'static_tool', description: 'static', inputSchema}, async () => 'success');
    const accessCountAfterRegister = accesses;
    for (let index = 0; index < 10; index++) {
      await registry.execute('static_tool', {});
    }
    expect(accesses).toBeLessThan(accessCountAfterRegister + 10);
  });

  it('still throws Unknown tool: <name> for an unregistered name, unchanged', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
  });

  it('produces no log line containing an identifying field value when payload is rejected', async () => {
    const logs: string[] = [];
    setLogger({
      debug: (category, message, fields) => logs.push(JSON.stringify({category, message, fields})),
      info: (category, message, fields) => logs.push(JSON.stringify({category, message, fields})),
      warn: (category, message, fields) => logs.push(JSON.stringify({category, message, fields})),
      error: (category, message, fields) => logs.push(JSON.stringify({category, message, fields})),
    });

    try {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'secret_tool',
          description: 'secret',
          inputSchema: {type: 'object', properties: {secretField: {type: 'number'}}, required: ['secretField']},
        },
        async () => 'success'
      );

      const response = await registry.execute('secret_tool', {secretField: 'TOP_SECRET_VALUE'});
      const allLogs = logs.join('\n');
      expect({
        leakedInResult: response.result.includes('TOP_SECRET_VALUE'),
        leakedInLogs: allLogs.includes('TOP_SECRET_VALUE'),
        allLogs,
      }).toEqual({
        leakedInResult: false,
        leakedInLogs: false,
        allLogs: expect.stringMatching(/secretField/),
      });
    } finally {
      setLogger(undefined);
    }
  });
});

